import React from 'react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  Brush,
  ReferenceLine,
  Area,
  AreaChart,
  ComposedChart
} from 'recharts';

// Fungsi helper untuk memformat tanggal
const formatDate = (dateString) => {
  const date = new Date(dateString);
  // Cek apakah tanggal valid
  if (isNaN(date.getTime())) return dateString;

  return date.toLocaleDateString('id-ID', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  });
};

// Fungsi helper untuk memformat angka sebagai mata uang
const formatCurrency = (value, currencySymbol = 'Rp') => {
  if (typeof value !== 'number') return '-';
  return `${currencySymbol} ${value.toLocaleString('id-ID')}`;
};

// Custom Tooltip komponen
const CustomTooltip = ({ active, payload, label, currencySymbol }) => {
  if (active && payload && payload.length) {
    const data = payload[0].payload;

    // Hitung perubahan harga dari titik sebelumnya jika tersedia
    const priceChange = data.previousClose ? data.Close - data.previousClose : 0;
    const percentChange = data.previousClose ? (priceChange / data.previousClose) * 100 : 0;
    const isPositive = priceChange >= 0;

    return (
      <div className="custom-tooltip" style={{ 
        backgroundColor: 'white',
        padding: '15px',
        border: `1px solid ${isPositive ? 'rgba(76, 175, 80, 0.3)' : 'rgba(229, 57, 53, 0.3)'}`,
        borderRadius: '8px',
        boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
        minWidth: '250px',
        transition: 'all 0.3s ease'
      }}>
        <p style={{ 
          fontWeight: 'bold', 
          marginBottom: '8px', 
          borderBottom: '1px solid #eee', 
          paddingBottom: '8px',
          fontSize: '16px',
          color: isPositive ? '#2E7D32' : '#C62828'
        }}>
          {formatDate(data.Date || data.Datetime)}
        </p>
        <div style={{ fontSize: '14px' }}>
          <p style={{ margin: '5px 0', display: 'flex', justifyContent: 'space-between' }}>
            <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Buka:</span>
            <span style={{ fontWeight: '600' }}>{formatCurrency(data.Open, currencySymbol)}</span>
          </p>
          <p style={{ margin: '5px 0', display: 'flex', justifyContent: 'space-between' }}>
            <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Tertinggi:</span>
            <span style={{ fontWeight: '600' }}>{formatCurrency(data.High, currencySymbol)}</span>
          </p>
          <p style={{ margin: '5px 0', display: 'flex', justifyContent: 'space-between' }}>
            <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Terendah:</span>
            <span style={{ fontWeight: '600' }}>{formatCurrency(data.Low, currencySymbol)}</span>
          </p>
          <p style={{ 
            margin: '5px 0', 
            display: 'flex', 
            justifyContent: 'space-between',
            backgroundColor: isPositive ? 'rgba(76, 175, 80, 0.1)' : 'rgba(229, 57, 53, 0.1)',
            padding: '5px 8px',
            borderRadius: '4px'
          }}>
            <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Tutup:</span>
            <span style={{ fontWeight: 'bold', fontSize: '16px', color: isPositive ? '#2E7D32' : '#C62828' }}>
              {formatCurrency(data.Close, currencySymbol)}
            </span>
          </p>
          {data.previousClose && (
            <p style={{ margin: '5px 0', display: 'flex', justifyContent: 'space-between' }}>
              <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Perubahan:</span>
              <span style={{ fontWeight: '600', color: isPositive ? '#2E7D32' : '#C62828' }}>
                {isPositive ? '+' : ''}{formatCurrency(priceChange, currencySymbol)} ({isPositive ? '+' : ''}{percentChange.toFixed(2)}%)
              </span>
            </p>
          )}
          <p style={{ 
            margin: '5px 0', 
            display: 'flex', 
            justifyContent: 'space-between', 
            borderTop: '1px solid #eee', 
            paddingTop: '8px', 
            marginTop: '8px' 
          }}>
            <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Volume:</span>
            <span style={{ fontWeight: '600' }}>{data.Volume.toLocaleString('id-ID')}</span>
          </p>
        </div>
      </div>
    );
  }

  return null;
};

const StockChart = ({ data, currencySymbol = 'Rp', chartType = 'composed' }) => {
  // Pastikan data tidak kosong
  if (!data || data.length === 0) {
    return (
      <div className="chart-container">
        <p>Tidak ada data yang tersedia untuk ditampilkan</p>
      </div>
    );
  }

  // Persiapkan data untuk chart (urutkan berdasarkan tanggal)
  const sortedData = [...data].sort((a, b) => {
    const dateA = new Date(a.Date || a.Datetime);
    const dateB = new Date(b.Date || b.Datetime);
    return dateA - dateB; // Ascending order for chart
  });

  // Tambahkan informasi previousClose untuk perhitungan perubahan
  const chartData = sortedData.map((item, index) => {
    if (index === 0) {
      return {
        ...item,
        previousClose: null
      };
    }

    const previousClose = sortedData[index - 1].Close;

    return {
      ...item,
      previousClose
    };
  });

  // Fungsi untuk menentukan apakah menampilkan semua titik data
  const shouldShowAllTicks = chartData.length <= 30;

  // Format ticks pada sumbu X
  const formatXAxis = (tickItem) => {
    const date = new Date(tickItem);
    if (isNaN(date.getTime())) return tickItem;

    // Format singkat (DD/MM) jika banyak data
    if (chartData.length > 30) {
      return date.toLocaleDateString('id-ID', {
        day: '2-digit',
        month: '2-digit'
      });
    }

    // Format lengkap jika sedikit data
    return date.toLocaleDateString('id-ID', {
      day: '2-digit',
      month: '2-digit',
      year: '2-digit'
    });
  };

  // Cari nilai min dan max untuk sumbu Y
  const minValue = Math.min(...chartData.map(item => item.Low));
  const maxValue = Math.max(...chartData.map(item => item.High));

  // Tambahkan sedikit margin untuk visualisasi yang lebih baik
  const yAxisDomain = [
    minValue - (minValue * 0.01), // 1% lebih rendah dari minimum
    maxValue + (maxValue * 0.01)  // 1% lebih tinggi dari maksimum
  ];

  // Dapatkan data harga terakhir dan perubahan
  const firstPrice = chartData[0]?.Close || 0;
  const lastPrice = chartData[chartData.length - 1]?.Close || 0;
  const overallChange = lastPrice - firstPrice;
  const overallPercentChange = (overallChange / firstPrice) * 100;
  const isPositiveOverall = overallChange >= 0;

  // Mendapatkan tanggal terakhir
  const lastDate = chartData[chartData.length - 1]?.Date || '';

  // Common chart props for consistent styling
  const commonChartProps = {
    margin: {
      top: 20,
      right: 30,
      left: 20,
      bottom: 50
    }
  };

  // Common axis props
  const xAxisProps = {
    dataKey: "Date",
    tickFormatter: formatXAxis,
    tick: { fontSize: 12, fill: '#555' },
    interval: shouldShowAllTicks ? 0 : 'preserveStartEnd',
    angle: -45,
    textAnchor: "end",
    height: 70,
    axisLine: { stroke: '#e0e0e0' },
    tickLine: { stroke: '#e0e0e0' }
  };

  const yAxisProps = {
    domain: yAxisDomain,
    tickFormatter: (value) => formatCurrency(value, currencySymbol),
    tick: { fontSize: 12, fill: '#555' },
    width: 90,
    axisLine: { stroke: '#e0e0e0' },
    tickLine: { stroke: '#e0e0e0' }
  };

  // Common grid props
  const gridProps = {
    strokeDasharray: "3 3",
    stroke: "#f0f0f0",
    vertical: false
  };

  // Common tooltip props
  const tooltipProps = {
    content: <CustomTooltip currencySymbol={currencySymbol} />,
    animationDuration: 300,
    animationEasing: "ease-out"
  };

  // Common legend props
  const legendProps = {
    verticalAlign: "top",
    height: 50,
    iconSize: 12,
    iconType: "circle",
    wrapperStyle: {
      paddingBottom: '15px',
      fontSize: '14px',
      fontWeight: '500'
    }
  };

  // Common brush props
  const brushProps = {
    dataKey: "Date",
    height: 35,
    stroke: isPositiveOverall ? '#4CAF50' : '#E53935',
    tickFormatter: formatXAxis,
    startIndex: Math.max(0, chartData.length - Math.min(60, chartData.length)),
    fill: "#ffffff",
    travellerWidth: 10,
    y: 5
  };

  return (
    <div className="chart-container" style={{
      padding: '15px',
      backgroundColor: '#f9f9f9',
      borderRadius: '16px',
      boxShadow: '0 2px 10px rgba(0,0,0,0.03)',
      transition: 'all 0.3s ease'
    }}>
      {/* Panel harga terakhir yang lebih menonjol */}
      <div style={{
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        padding: '20px 25px',
        backgroundColor: 'white',
        borderRadius: '12px',
        boxShadow: '0 4px 16px rgba(0,0,0,0.08)',
        marginBottom: '25px',
        border: `1px solid ${isPositiveOverall ? 'rgba(76, 175, 80, 0.2)' : 'rgba(229, 57, 53, 0.2)'}`,
        transition: 'all 0.3s ease',
        background: `linear-gradient(to right, white, ${isPositiveOverall ? 'rgba(76, 175, 80, 0.05)' : 'rgba(229, 57, 53, 0.05)'})`
      }}>
        <div>
          <div style={{ 
            fontSize: '14px', 
            color: '#666', 
            marginBottom: '6px',
            fontWeight: '500',
            display: 'flex',
            alignItems: 'center'
          }}>
            <span style={{
              display: 'inline-block',
              width: '8px',
              height: '8px',
              borderRadius: '50%',
              backgroundColor: isPositiveOverall ? '#4CAF50' : '#E53935',
              marginRight: '8px'
            }}></span>
            {formatDate(lastDate)} - Harga Terakhir
          </div>
          <div style={{ 
            fontSize: '28px', 
            fontWeight: 'bold', 
            color: isPositiveOverall ? '#2E7D32' : '#C62828',
            letterSpacing: '-0.5px'
          }}>
            {formatCurrency(lastPrice, currencySymbol)}
          </div>
        </div>
        <div style={{ 
          textAlign: 'right',
          backgroundColor: isPositiveOverall ? 'rgba(76, 175, 80, 0.1)' : 'rgba(229, 57, 53, 0.1)',
          padding: '12px 16px',
          borderRadius: '8px'
        }}>
          <div style={{ 
            fontSize: '14px', 
            color: '#666', 
            marginBottom: '6px',
            fontWeight: '500'
          }}>
            Perubahan
          </div>
          <div style={{ 
            fontSize: '22px', 
            fontWeight: 'bold', 
            color: isPositiveOverall ? '#2E7D32' : '#C62828',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'flex-end'
          }}>
            <div>
              {isPositiveOverall ? '+' : ''}{formatCurrency(overallChange, currencySymbol)}
            </div>
            <div style={{ 
              fontSize: '16px',
              backgroundColor: isPositiveOverall ? 'rgba(76, 175, 80, 0.2)' : 'rgba(229, 57, 53, 0.2)',
              padding: '3px 8px',
              borderRadius: '4px',
              marginTop: '4px'
            }}>
              {isPositiveOverall ? '+' : ''}{overallPercentChange.toFixed(2)}%
            </div>
          </div>
        </div>
      </div>

      <div className="chart-wrapper" style={{ 
        position: 'relative',
        backgroundColor: 'white',
        borderRadius: '12px',
        padding: '25px',
        boxShadow: '0 4px 16px rgba(0,0,0,0.08)',
        border: `1px solid ${isPositiveOverall ? 'rgba(76, 175, 80, 0.2)' : 'rgba(229, 57, 53, 0.2)'}`,
        transition: 'all 0.3s ease',
        marginTop: '20px'
      }}>
        <ResponsiveContainer width="100%" height={450}>
          {chartType === 'line' ? (
            <LineChart
              data={chartData}
              {...commonChartProps}
            >
              <CartesianGrid {...gridProps} />
              <XAxis {...xAxisProps} />
              <YAxis {...yAxisProps} />
              <Tooltip {...tooltipProps} />
              <Legend {...legendProps} />

              {/* Garis utama */}
              <Line
                type="monotone"
                dataKey="Close"
                name="Harga Penutupan"
                stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                strokeWidth={2.5}
                dot={{ r: 2, fill: isPositiveOverall ? '#4CAF50' : '#E53935', strokeWidth: 1, stroke: 'white' }}
                activeDot={{ 
                  r: 7, 
                  fill: isPositiveOverall ? '#4CAF50' : '#E53935',
                  stroke: 'white',
                  strokeWidth: 2
                }}
                animationDuration={1500}
                animationEasing="ease-in-out"
              />

              {/* Garis referensi untuk menunjukkan harga awal */}
              <ReferenceLine 
                y={firstPrice} 
                stroke="#888" 
                strokeDasharray="3 3" 
                label={{ 
                  value: `Awal: ${formatCurrency(firstPrice, currencySymbol)}`,
                  position: 'left',
                  fill: '#666',
                  fontSize: 12,
                  fontWeight: '500',
                  backgroundColor: 'white',
                  padding: 5
                }} 
              />

              <Brush
                dataKey="Date"
                height={35}
                stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                tickFormatter={formatXAxis}
                startIndex={Math.max(0, chartData.length - Math.min(60, chartData.length))}
                fill="#ffffff"
                travellerWidth={10}
                y={5}
              />
            </LineChart>
          ) : chartType === 'area' ? (
            <AreaChart
              data={chartData}
              margin={{
                top: 20,
                right: 30,
                left: 20,
                bottom: 50
              }}
            >
              <defs>
                <linearGradient id="colorClose" x1="0" y1="0" x2="0" y2="1">
                  <stop 
                    offset="5%" 
                    stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'} 
                    stopOpacity={0.25}
                  />
                  <stop 
                    offset="95%" 
                    stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'} 
                    stopOpacity={0}
                  />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" vertical={false} />
              <XAxis
                dataKey="Date"
                tickFormatter={formatXAxis}
                tick={{ fontSize: 12, fill: '#666' }}
                interval={shouldShowAllTicks ? 0 : 'preserveStartEnd'}
                angle={-45}
                textAnchor="end"
                height={70}
                axisLine={{ stroke: '#e0e0e0' }}
                tickLine={{ stroke: '#e0e0e0' }}
              />
              <YAxis
                domain={yAxisDomain}
                tickFormatter={(value) => formatCurrency(value, currencySymbol)}
                tick={{ fontSize: 12, fill: '#666' }}
                width={90}
                axisLine={{ stroke: '#e0e0e0' }}
                tickLine={{ stroke: '#e0e0e0' }}
              />
              <Tooltip 
                content={<CustomTooltip currencySymbol={currencySymbol} />}
                animationDuration={300}
                animationEasing="ease-out"
              />
              <Legend 
                verticalAlign="top" 
                height={50}
                iconSize={12}
                iconType="circle"
                wrapperStyle={{
                  paddingBottom: '15px',
                  fontSize: '14px',
                  fontWeight: '500'
                }}
              />

              {/* Area untuk visualisasi */}
              <Area
                type="monotone"
                dataKey="Close"
                name="Area Harga"
                fill="url(#colorClose)"
                stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                strokeWidth={2}
                animationDuration={1500}
                animationEasing="ease-in-out"
              />

              {/* Garis referensi untuk menunjukkan harga awal */}
              <ReferenceLine 
                y={firstPrice} 
                stroke="#888" 
                strokeDasharray="3 3" 
                label={{ 
                  value: `Awal: ${formatCurrency(firstPrice, currencySymbol)}`,
                  position: 'left',
                  fill: '#666',
                  fontSize: 12,
                  fontWeight: '500',
                  backgroundColor: 'white',
                  padding: 5
                }} 
              />

              <Brush
                dataKey="Date"
                height={35}
                stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                tickFormatter={formatXAxis}
                startIndex={Math.max(0, chartData.length - Math.min(60, chartData.length))}
                fill="#ffffff"
                travellerWidth={10}
                y={5}
              />
            </AreaChart>
          ) : (
            <ComposedChart
              data={chartData}
              margin={{
                top: 20,
                right: 30,
                left: 20,
                bottom: 50
              }}
            >
              <defs>
                <linearGradient id="colorClose" x1="0" y1="0" x2="0" y2="1">
                  <stop 
                    offset="5%" 
                    stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'} 
                    stopOpacity={0.25}
                  />
                  <stop 
                    offset="95%" 
                    stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'} 
                    stopOpacity={0}
                  />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="#e0e0e0" vertical={false} />
              <XAxis
                dataKey="Date"
                tickFormatter={formatXAxis}
                tick={{ fontSize: 12, fill: '#666' }}
                interval={shouldShowAllTicks ? 0 : 'preserveStartEnd'}
                angle={-45}
                textAnchor="end"
                height={70}
                axisLine={{ stroke: '#e0e0e0' }}
                tickLine={{ stroke: '#e0e0e0' }}
              />
              <YAxis
                domain={yAxisDomain}
                tickFormatter={(value) => formatCurrency(value, currencySymbol)}
                tick={{ fontSize: 12, fill: '#666' }}
                width={90}
                axisLine={{ stroke: '#e0e0e0' }}
                tickLine={{ stroke: '#e0e0e0' }}
              />
              <Tooltip 
                content={<CustomTooltip currencySymbol={currencySymbol} />}
                animationDuration={300}
                animationEasing="ease-out"
              />
              <Legend 
                verticalAlign="top" 
                height={50}
                iconSize={12}
                iconType="circle"
                wrapperStyle={{
                  paddingBottom: '15px',
                  fontSize: '14px',
                  fontWeight: '500'
                }}
              />

              {/* Area di bawah garis untuk visualisasi lebih baik */}
              <Area
                type="monotone"
                dataKey="Close"
                name="Area Harga"
                fill="url(#colorClose)"
                stroke="none"
                animationDuration={1500}
                animationEasing="ease-in-out"
              />

              {/* Garis utama */}
              <Line
                type="monotone"
                dataKey="Close"
                name="Harga Penutupan"
                stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                strokeWidth={2.5}
                dot={{ r: 2, fill: isPositiveOverall ? '#4CAF50' : '#E53935', strokeWidth: 1, stroke: 'white' }}
                activeDot={{ 
                  r: 7, 
                  fill: isPositiveOverall ? '#4CAF50' : '#E53935',
                  stroke: 'white',
                  strokeWidth: 2
                }}
                animationDuration={1500}
                animationEasing="ease-in-out"
              />

              {/* Garis referensi untuk menunjukkan harga awal */}
              <ReferenceLine 
                y={firstPrice} 
                stroke="#888" 
                strokeDasharray="3 3" 
                label={{ 
                  value: `Awal: ${formatCurrency(firstPrice, currencySymbol)}`,
                  position: 'left',
                  fill: '#666',
                  fontSize: 12,
                  fontWeight: '500',
                  backgroundColor: 'white',
                  padding: 5
                }} 
              />

              <Brush
                dataKey="Date"
                height={35}
                stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                tickFormatter={formatXAxis}
                startIndex={Math.max(0, chartData.length - Math.min(60, chartData.length))}
                fill="#ffffff"
                travellerWidth={10}
                y={5}
              />
            </ComposedChart>
          )}
        </ResponsiveContainer>
      </div>
    </div>
  );
};

export default StockChart;
